    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx)); stack.append((ny, nx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            ih, iw = y1-y0-1, x1-x0-1
            if ih > 0 and iw > 0:
